def sumofFactors(n: int) -> int:
    """Return the sum of all even factors of n."""
    if n <= 0:
        return 0

    total = 0
    i = 2
    while i * i <= n:
        if n % i == 0:
            # i is a factor, and 2*i is also a factor
            # Add both even factors
            total += i + 2 * i
            # Add higher powers of i
            k = i
            while n % k == 0:
                if k % 2 == 0:
                    total += k
                k *= i
        i += 1

    if n > 1 and n % 2 == 0:
        total += n

    return total
