def is_simple_power(x, n):
    """Returns True if x is a simple power of n (i.e., x == n**k for some integer k), False otherwise."""
    if not (isinstance(x, int) and isinstance(n, int)):
        return False
    if n == 1:
        return x == 1
    k_min = 0
    # Determine the maximum possible exponent k such that n**k <= x
    # This avoids floating point inaccuracies when computing n**k directly
    k = 0
    while n ** (k + 1) <= x:
        k += 1

    # Check if any n**k equals x
    for exponent in range(k_min, k + 1):
        if n ** exponent == x:
            return True
    return False
