def dict_depth(d):
    """
    Calculate the depth of a dictionary.
    Depth is defined as the maximum nesting level of the dictionary.
    - An empty dict or a dict with only non-dict/non-list values has depth 1.
    - A dict containing nested dicts or lists that may contain dicts increases the depth.
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    max_depth = 1

    for value in d.values():
        if isinstance(value, dict):
            # Recursively compute depth for nested dicts
            nested_depth = dict_depth(value)
            if nested_depth + 1 > max_depth:
                max_depth = nested_depth + 1
        elif isinstance(value, list):
            # Iterate through list items; if any is a dict, it adds to depth
            for item in value:
                if isinstance(item, dict):
                    nested_depth = dict_depth(item)
                    if nested_depth + 2 > max_depth:
                        max_depth = nested_depth + 2
        # Other types (int, str, bool, None) do not increase depth beyond the current level

    return max_depth
```

