def next_smallest_palindrome(n: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(abs(x))
        return s == s[::-1]

    def next_palindrome(x: int) -> int:
        if x < 0:
            # Handle negative numbers by considering their absolute value
            # and returning the next palindrome in magnitude, keeping sign
            base = -x
            while True:
                cand = base + 1
                if is_palindrome(cand):
                    return -cand
        else:
            while True:
                cand = x + 1
                if is_palindrome(cand):
                    return cand

    return next_palindrome(n)
