def add_nested_tuples(t1, t2):
    """
    Performs element-wise addition of two nested tuples.
    Both tuples must be of the same dimensions (depth and size at each level).

    Parameters:
        t1 (tuple): First nested tuple.
        t2 (tuple): Second nested tuple.

    Returns:
        tuple: A nested tuple with the sum of corresponding elements.

    Raises:
        ValueError: If the dimensions of t1 and t2 do not match.
        TypeError: If inputs are not tuples.
    """
    if not isinstance(t1, tuple) or not isinstance(t2, tuple):
        raise TypeError("Both inputs must be tuples.")

    def _check_and_add(a, b, depth):
        if depth == 0:
            if a != b:
                raise ValueError(f"Dimensions do not match at depth {depth}. Lengths differ: {len(a)} vs {len(b)}.")
            return tuple(x + y for x, y in zip(a, b))
        else:
            if len(a) != len(b):
                raise ValueError(f"Dimensions do not match at depth {depth}. Number of sub-tuples differ: {len(a)} vs {len(b)}.")
            return tuple(_check_and_add(x, y, depth + 1) for x, y in zip(a, b))

    return _check_and_add(t1, t2, 0)
```

