def add_nested_tuples(t1, t2):
    """
    Perform index-wise addition of elements in two nested tuples of the same structure.

    Args:
        t1 (tuple): First nested tuple.
        t2 (tuple): Second nested tuple (must have the same structure as t1).

    Returns:
        tuple: A new nested tuple with elements added index-wise.

    Raises:
        ValueError: If the structures of t1 and t2 do not match.
        TypeError: If inputs are not tuples.
    """
    if not isinstance(t1, tuple) or not isinstance(t2, tuple):
        raise TypeError("Both inputs must be tuples.")

    def _check_and_add(t1_node, t2_node):
        if not isinstance(t1_node, type(t2_node)) or len(t1_node) != len(t2_node):
            raise ValueError("Tuples must have the same structure and same length at each level.")

        result = []
        for a, b in zip(t1_node, t2_node):
            if isinstance(a, tuple):
                if not isinstance(b, tuple):
                    raise ValueError("Mismatched structures detected.")
                nested_result = _check_and_add(a, b)
                result.append(nested_result)
            else:
                result.append(a + b)
        return tuple(result)

    return _check_and_add(t1, t2)
