def is_majority(arr, n, element):
    if n == 0:
        return False
    # Since the array is sorted, the element must appear at position
    # (count // 2) to satisfy the majority condition.
    # We can use binary search to find the first and last occurrence.
    left, right = 0, n - 1

    # Find first occurrence
    first = n
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == element:
            first = mid
            right = mid - 1
        elif arr[mid] < element:
            left = mid + 1
        else:
            right = mid - 1

    if first == n:
        return False

    # Find last occurrence
    last = -1
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == element:
            last = mid
            left = mid + 1
        elif arr[mid] < element:
            left = mid + 1
        else:
            right = mid - 1

    count = last - first + 1
    return count > n / 2
```

